INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Vikram Seth', 'Vikram Seth was born on June 20, 1952 in Calcutta, India. He is a writer and actor, known for Highway (2014), A Suitable Boy (2020) and Omnibus (1967).', 'https://m.media-amazon.com/images/M/MV5BMjE5NjkyNTczM15BMl5BanBnXkFtZTgwNDg4MzE5MDE@._V1_QL75_UY133_CR1,0,90,133_.jpg', '1952-06-20', NULL, NOW(6), NOW(6), 0, 'ADMIN');
