INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('R.K. Narayan', 'R.K. Narayan was born on October 10, 1906 in Madras, Madras Presidency, British India. R.K. was a writer, known for Guide (1965), Banker Margayya (1983) and The Guide (1965). R.K. died on May 13, 2001 in New Delhi, India.', 'https://m.media-amazon.com/images/M/MV5BYjlhNWRjY2UtYjlmNC00NzFiLWFiZTQtNmU3NTBkNmQ5N2JiXkEyXkFqcGc@._V1_QL75_UX90_CR0,1,90,133_.jpg', '1906-10-10', NULL, NOW(6), NOW(6), 0, 'ADMIN');
