INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Anita Desai', 'Anita Desai was born on June 24, 1937 in Mussoorie, India. She is a writer, known for In Custody (1994), The Village by the Sea (1991) and In Ismail''s Custody (1994).', 'https://m.media-amazon.com/images/M/MV5BMTUxODc2NTk2MV5BMl5BanBnXkFtZTYwMzg1NjEz._V1_QL75_UY207_CR19,0,140,207_.jpg', '1937-06-24', NULL, NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Khushwant Singh', 'Khushwant Singh was born on February 2, 1915 in Hadali, Khushab district, Punjab, British India. He was an actor and writer, known for Train to Pakistan (1998), Songs and Memories (1992) and Modern India (1960). He was married to Kawal Malik. He died on March 20, 2014 in New Delhi, India.', 'https://m.media-amazon.com/images/M/MV5BMDEzOTY3N2MtNDA2NS00YmEzLTljNTItMDcwOWU1OTc0MTc0XkEyXkFqcGc@._V1_QL75_UY133_CR2,0,90,133_.jpg', '1915-02-02', NULL, NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Ruskin Bond', 'Ruskin Bond was born on May 19, 1934 in Kasauli, Punjab, British India. He is a writer and actor, known for The Blue Umbrella (2005), Junoon (1979) and 7 Khoon Maaf (2011).', 'https://m.media-amazon.com/images/M/MV5BNTAyOTRkY2YtZWM4NS00Yzk1LWFhZjAtYzIxZjY5NDNmZGU2XkEyXkFqcGc@._V1_QL75_UY207_CR72,0,140,207_.jpg', '1934-05-19', NULL, NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('V.S. Naipaul', 'V.S. Naipaul was born on August 17, 1932 in Chaguanas, Trinidad, Trinidad and Tobago. He was a writer, known for The Mystic Masseur (2001), The Levin Interviews (1980) and Bookmark (1983). He was married to Nadira Khannum Alvi and Patricia Ann Hale. He died on August 11, 2018 in London, England, UK.', 'https://m.media-amazon.com/images/M/MV5BZDcwYjUzZmUtNmViZS00MjM1LWIyZTQtODgxNDJiYjlkNDU1XkEyXkFqcGc@._V1_QL75_UY207_CR1,0,140,207_.jpg', '1932-08-17', NULL, NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Rohinton Mistry', 'Rohinton Mistry was born in 1952 in Bombay, India. Rohinton is a writer, known for Such a Long Journey (1998) and A Fine Balance. Rohinton is married to Freny Elavia.', 'https://m.media-amazon.com/images/M/MV5BNzA1MTkxNTgzMl5BMl5BanBnXkFtZTcwMDk0ODUyMQ@@._V1_QL75_UY133_CR2,0,90,133_.jpg', NULL, NULL, NOW(6), NOW(6), 0, 'ADMIN');
