INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Shashi Tharoor', 'Shashi Tharoor was born on March 9, 1956 in London, England, UK. He is a writer, known for Bollywood (1994), U.N. Me (2009) and 8 Billion Angels (2019).', 'https://m.media-amazon.com/images/M/MV5BM2ZmMDVlNDQtOTBkYi00MmZiLWE0NGQtMzg2ZjViMjI3ZDJjXkEyXkFqcGc@._V1_QL75_UX83_.jpg', '1956-03-09', NULL, NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Rabindranath Tagore', 'Rabindranath Tagore was born on May 6, 1861 in Calcutta, Bengal Presidency, British India [now India]. He was a writer and composer, known for Song of the Body, Streer Patra (1972) and Charulata (1964). He was married to Mrinalini Devi. He died on August 7, 1941 in Calcutta, Bengal Presidency, British India [now India].', 'https://m.media-amazon.com/images/M/MV5BODFlYTZhMmYtNmU1NC00NDQyLTg5NzQtNThhZTBlNDVhYWExXkEyXkFqcGc@._V1_QL75_UY207_CR5,0,140,207_.jpg', '1861-05-06', NULL, NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Shobha De', 'Shobha De was born on January 7, 1948 in Bombay, State of Bombay, India. She is a writer and actress, known for Swabhimaan (1995), Lipstick (2002) and Sarrrkkar: Risshton Ki Ankahi Kahani.', 'https://m.media-amazon.com/images/M/MV5BMGU3NGFkZmMtNWE2OC00ZmE5LTg3ZDctZDM0MzhhM2NjMWQwXkEyXkFqcGc@._V1_QL75_UX140_CR0,1,140,207_.jpg', '1948-01-07', NULL, NOW(6), NOW(6), 0, 'ADMIN');
