INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Satyajit Ray', 'w.imdb.com/name/nm0006249/?ref_=nm_ov_bio_lk) was born in Calcutta on May 2, 1921. His father, Late Sukumar Ray was an eminent poet and writer in the history of Bengali literature. In 1940, after receiving his degree in science and economics from Calcutta University, he attended Tagore''s Viswa-Bharati University. His first movie Pather Panchali (1955) won several International Awards and set Ray as a world-class director. He died on April twenty-third, 1992.
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Mahasweta Devi', 'Mahasweta Devi was born on January 14, 1926 in Dacca, Bengal Presidency, British India [now in Dhaka, Bangladesh]. She was a writer, known for Sunghursh (1968), Gudia (1997) and Maati Maay (2006). She was married to Asit Gupta and Bijon Bhattacharya. She died on July 28, 2016 in Kolkata, West Bengal, India.', 'https://m.media-amazon.com/images/M/MV5BZWQ3NTJmMGQtOTc4ZS00MGIzLThhNTItMjI3YWU0YTczZjk3XkEyXkFqcGc@._V1_QL75_UY133_CR3,0,90,133_.jpg', '1926-01-14', NULL, NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Jawaharlal Nehru', 'Jawaharlal Nehru was born on November 14, 1889, in Allahabad, India. He was the son of Swaroop Rani and Motilal Nehru, a wealthy lawyer and a prominent leader of the Indian independence movement. The Nehru family belonged to the saraswat Brahmin caste. Nehru graduated from Trinity College, Cambridge University and came back to India in 1912. In 1916, by his parents'' arrangement, he married 17-year-old Kamala from a Kashmiri business family in Delhi. He became the top political leader of the Indian National Congress Party along with his mentor, Mohandas K. Gandhi.
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Mohandas K. Gandhi', 'Mohandas Karamchand Gandhi (Mahatma Gandhi) was born on October 2, 1869, into a Hindu Modh family in Porbanadar, Gujarat, India. His father, named Karamchand Gandhi, was the Chief Minister (diwan) of the city of Porbanadar. His mother, named Putlibai, was the fourth wife; the previous three wives died in childbirth. Gandhi was born into the vaishya (business caste). He was 13 years old when married Kasturbai (Ba) Makhanji, through his parents arrangement. They had four sons. Gandhi learned tolerance and non-injury to living beings from an early age. He was abstinent from meat, alcohol, and promiscuity.
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Ajeet Bharti', 'Indian independent journalist, author and media creator. He has worked with Times of India, Economic Times and IANS, later became founding editor of OpIndia Hindi, co-founded DO Politics, and heads AB4K Media. His books include Bakar Puran, Ghar Wapasi, There Will Be No Love, and Jo Bhi Kahunga Sach Kahunga.', 'https://www.hindustantimes.com/ht-img/img/2025/10/08/440x440/ajeet_bharti_1759869848810_1759869859528_1759897695382.jpg', '1994-09-24', 'Ratan Babhangaon, Begusarai, Bihar, India', NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Kushal Mehra', 'Indian podcaster, author and former textile entrepreneur based in Mumbai. He hosts the Cārvāka Podcast and describes his work as articulating Indian scepticism using Indian epistemological frameworks. He holds a master''s degree in philosophy and has written books including Nastik: Why I Am Not An Atheist and Blasphemy: Let Me Speak.', NULL, NULL, NULL, NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('J. Sai Deepak', 'Indian lawyer, author, columnist and public speaker. He is an engineer-turned-litigator practising primarily before the Supreme Court of India and the High Court of Delhi. He is the author of India That Is Bharat and India, Bharat and Pakistan.', NULL, '1985-11-23', 'Hyderabad, Telangana, India', NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Vikram Sampath', 'Indian historian, biographer and columnist known for biographies and works on Indian history and culture, including books on Gauhar Jaan, Savarkar and the Wadiyar dynasty of Mysore. He is a Fellow of the Royal Historical Society and founder of the Bangalore Literature Festival.', NULL, NULL, 'Bengaluru, Karnataka, India', NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Anand Ranganathan', 'Indian molecular biologist, professor, columnist and author. He is a professor at Jawaharlal Nehru University''s Special Centre for Molecular Medicine. His books include The Land of the Wilted Rose, For Love and Honour, The Rat Eater, Soufflé, and Hindus in Hindu Rashtra.', NULL, '1972-12-04', 'Tamil Nadu, India', NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Arun Shourie', 'Indian economist, investigative journalist, editor, author and former Union minister. He worked with the World Bank, edited The Indian Express and The Times of India, and served in the Vajpayee government. He is the author of numerous books on politics, religion, society and public affairs.', 'https://litfest.sgp1.cdn.digitaloceanspaces.com/uploads/authors/a-Zc5ss3CLGPWrn7LakKq7HRs9K7iHR7-metaMjguanBn-.jpg', '1941-11-02', 'Jalandhar, Punjab, India', NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Rajiv Malhotra', 'Indian-born American author, researcher and public intellectual focused on civilizations, Indian knowledge systems, religions and cross-cultural encounters. He founded Infinity Foundation and has authored books including Breaking India, Being Different, Indra''s Net and The Battle for Sanskrit.', NULL, '1950-09-15', 'New Delhi, Delhi, India', NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Meenakshi Jain', 'Indian historian and political scientist, formerly an associate professor of history at Gargi College, University of Delhi. Her research covers cultural and religious developments in medieval and early modern India. Her books include The Battle for Rama, Rama and Ayodhya, Sati, Flight of Deities and Rebirth of Temples, and Vishwanath Rises and Rises.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Meenakshi%20Jain.jpg', NULL, 'Delhi, India', NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('S. Gurumurthy', 'Swaminathan Gurumurthy is an Indian chartered accountant, columnist, economist and public intellectual. He is known for writing and speaking on economics, public policy, Indian civilization and political affairs, and has served in prominent public and institutional roles.', 'https://www.newsclick.in/sites/default/files/styles/amp_1200x675_16_9/public/2020-01/S%20Gurumurthy.jpeg?itok=g8xGjkSg', '1949-02-06', NULL, NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Swapan Dasgupta', 'Indian journalist, writer, political analyst and politician. He has written extensively on Indian politics, culture and Hindu nationalism and has served as a nominated member of the Rajya Sabha and in other public roles.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Swapan%20Dasgupta%20in%20May%202016.jpg', '1955-10-03', 'Kolkata, West Bengal, India', NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Ram Madhav', 'Indian politician, social leader, strategic thinker and author. He served as National General Secretary of the Bharatiya Janata Party from 2014 to 2020 and is associated with the India Foundation. His books include The New World, The Indian Reality, Partitioned Freedom and The Hindutva Paradigm.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ram%20Madhav%20at%20CPAC%20Hungary%202025.jpg', '1964-08-22', 'Amalapuram, Andhra Pradesh, India', NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Sanjeev Sanyal', 'Indian economist, writer and economic-policy adviser. He has served as Principal Economic Adviser in the Ministry of Finance and as a member of the Economic Advisory Council to the Prime Minister. He is also known for books on Indian history, geography and economic development.', NULL, '1970-08-27', 'Kolkata, West Bengal, India', NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Harsh Madhusudan', 'India-based public-markets investor and writer who has written on economics, finance and politics for publications including Mint, Swarajya, The Wall Street Journal, The Hindu Business Line and The Indian Express. He co-authored A New Idea of India with Rajeev Mantri.', NULL, NULL, NULL, NOW(6), NOW(6), 0, 'ADMIN');
INSERT INTO authors (name, biography, profile_image, date_of_birth, place_of_birth, created_at, updated_at, version, author_type) VALUES ('Koenraad Elst', 'Belgian author and orientalist whose work focuses heavily on Hinduism, Indian history, politics, comparative religion and the Hindutva movement. He has written extensively on the Ayodhya dispute and the Out-of-India theory and has worked as an independent researcher and writer.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Koenraad%20Elst%20at%20Varanasi.jpg', '1959-08-07', 'Leuven, Belgium', NOW(6), NOW(6), 0, 'ADMIN');